prompt ... Theme Styles
declare
  procedure upsert_style(p_name varchar2, p_static_id varchar2, p_css varchar2) is
    l_id number;
  begin
    select max(theme_style_id) into l_id
      from apex_application_theme_styles
     where application_id = wwv_flow_application_install.get_application_id
       and theme_number = 145
       and name = p_name;
    -- p_is_current => false lässt einen bereits aktuellen Style aktuell
    wwv_flow_imp_shared.create_theme_style(
      p_id                     => l_id,
      p_theme_id               => 145,
      p_name                   => p_name,
      p_static_id              => p_static_id,
      p_css_file_urls          => p_css,
      p_is_current             => false,
      p_is_public              => true,
      p_is_accessible          => false,
      p_theme_roller_read_only => true);
  end upsert_style;
begin
  upsert_style(
    p_name      => 'Kracherl Light',
    p_static_id => 'kracherl-light',
    p_css       => '#THEME_FILES#css/Vita#MIN#.css?v=#APEX_VERSION#' || chr(10) || '#THEME_DB_FILES#kracherl-light#MIN#.css?v=1.0.0');
  upsert_style(
    p_name      => 'Kracherl Dark',
    p_static_id => 'kracherl-dark',
    p_css       => '#THEME_FILES#css/Vita-Dark#MIN#.css?v=#APEX_VERSION#' || chr(10) || '#THEME_DB_FILES#kracherl-dark#MIN#.css?v=1.0.0');
  upsert_style(
    p_name      => 'Kracherl Auto',
    p_static_id => 'kracherl-auto',
    p_css       => '#THEME_FILES#css/Vita#MIN#.css?v=#APEX_VERSION#' || chr(10) || '#THEME_DB_FILES#kracherl-auto#MIN#.css?v=1.0.0');
end;
/
begin
  wwv_flow_imp.component_end(p_auto_install_sup_obj => false, p_is_component_import => true);
  commit;
end;
/

prompt ... aktuellen Style des Themes setzen
declare
  l_app_id   number := wwv_flow_application_install.get_application_id;
  l_current  varchar2(255);
  l_name     varchar2(255);
  l_style_id number;
  l_page_id  number;
  l_owner    varchar2(128);
begin
  select current_theme_style into l_current
    from apex_application_themes
   where application_id = l_app_id and theme_number = 145;
  if '&ACTIVATE.' is null and l_current in ('Kracherl Light', 'Kracherl Dark', 'Kracherl Auto') then
    dbms_output.put_line('Aktueller Style bleibt: ' || l_current);
    return;
  end if;
  l_name := case upper(nvl('&ACTIVATE.', 'light'))
      when 'LIGHT' then 'Kracherl Light'
      when 'DARK' then 'Kracherl Dark'
      when 'AUTO' then 'Kracherl Auto'
    end;
  select theme_style_id into l_style_id
    from apex_application_theme_styles
   where application_id = l_app_id and theme_number = 145 and name = l_name;
  select min(page_id) into l_page_id
    from apex_application_pages
   where application_id = l_app_id and page_id > 0;
  select owner into l_owner from apex_applications where application_id = l_app_id;
  apex_session.create_session(p_app_id => l_app_id, p_page_id => l_page_id, p_username => l_owner);
  apex_theme.set_current_style(p_application_id => l_app_id, p_theme_number => 145, p_id => to_char(l_style_id));
  apex_session.delete_session;
  commit;
  dbms_output.put_line('Aktueller Style des Themes: ' || l_name);
end;
/

set heading on pagesize 50 linesize 200
column theme_name format a20
column current_theme_style format a24
column version format a8
column is_current format a10
column reference_id format 99999999999999999999
column name format a24
column file_name format a60
prompt
prompt Themes der App:
select theme_number, theme_name, is_current, current_theme_style, version, reference_id
  from apex_application_themes
 where application_id = wwv_flow_application_install.get_application_id
 order by theme_number;
prompt Styles und Dateien des Themes Kracherl:
select name, is_current
  from apex_application_theme_styles
 where application_id = wwv_flow_application_install.get_application_id
   and theme_number = 145
   and name in ('Kracherl Light', 'Kracherl Dark', 'Kracherl Auto')
 order by name;
select file_name, dbms_lob.getlength(file_content) bytes
  from apex_application_theme_files
 where application_id = wwv_flow_application_install.get_application_id
   and theme_number = 145
 order by file_name;

prompt ... Abgleich mit dem Universal Theme
declare
  l_app_id number := wwv_flow_application_install.get_application_id;
  l_ut     apex_application_themes%rowtype;
  l_pp     apex_application_themes%rowtype;
  l_diff   pls_integer := 0;
  procedure cmp(p_what varchar2, p_ut varchar2, p_pp varchar2) is
  begin
    if nvl(p_ut, '-') <> nvl(p_pp, '-') then
      l_diff := l_diff + 1;
      dbms_output.put_line('  abweichend: ' || p_what || ' – UT: ' || nvl(p_ut, '-') || ', Kracherl: ' || nvl(p_pp, '-'));
    end if;
  end cmp;
begin
  select * into l_pp from apex_application_themes where application_id = l_app_id and theme_number = 145;
  if l_pp.reference_id is null then
    dbms_output.put_line('(entkoppelte Kopie mit eigenen Templates – Abgleich mit dem Universal Theme entfällt)');
    return;
  end if;
  select * into l_ut from apex_application_themes where application_id = l_app_id and theme_number = 42;
  cmp('reference_id', l_ut.reference_id, l_pp.reference_id);
  cmp('file_prefix', l_ut.file_prefix, l_pp.file_prefix);
  cmp('default_page_template', l_ut.default_page_template, l_pp.default_page_template);
  cmp('default_dialog_template', l_ut.default_dialog_template, l_pp.default_dialog_template);
  cmp('default_button_template', l_ut.default_button_template, l_pp.default_button_template);
  cmp('default_region_template', l_ut.default_region_template, l_pp.default_region_template);
  cmp('default_chart_rg_template', l_ut.default_chart_rg_template, l_pp.default_chart_rg_template);
  cmp('default_form_rg_template', l_ut.default_form_rg_template, l_pp.default_form_rg_template);
  cmp('default_report_region_template', l_ut.default_report_region_template, l_pp.default_report_region_template);
  cmp('default_tabular_form_template', l_ut.default_tabular_form_template, l_pp.default_tabular_form_template);
  cmp('default_wizard_template', l_ut.default_wizard_template, l_pp.default_wizard_template);
  cmp('default_breadcrumb_rg_template', l_ut.default_breadcrumb_rg_template, l_pp.default_breadcrumb_rg_template);
  cmp('default_list_region_template', l_ut.default_list_region_template, l_pp.default_list_region_template);
  cmp('default_irr_template', l_ut.default_irr_template, l_pp.default_irr_template);
  cmp('default_dialogr_template', l_ut.default_dialogr_template, l_pp.default_dialogr_template);
  cmp('default_dialogbtnr_template', l_ut.default_dialogbtnr_template, l_pp.default_dialogbtnr_template);
  cmp('default_report_row_template', l_ut.default_report_row_template, l_pp.default_report_row_template);
  cmp('default_item_label_template', l_ut.default_item_label_template, l_pp.default_item_label_template);
  cmp('default_option_label', l_ut.default_option_label, l_pp.default_option_label);
  cmp('default_required_label', l_ut.default_required_label, l_pp.default_required_label);
  cmp('default_breadcrumb_template', l_ut.default_breadcrumb_template, l_pp.default_breadcrumb_template);
  cmp('default_calendar_template', l_ut.default_calendar_template, l_pp.default_calendar_template);
  cmp('default_list_template', l_ut.default_list_template, l_pp.default_list_template);
  cmp('default_nav_list_template', l_ut.default_nav_list_template, l_pp.default_nav_list_template);
  cmp('default_top_nav_list_template', l_ut.default_top_nav_list_template, l_pp.default_top_nav_list_template);
  cmp('default_side_nav_list_template', l_ut.default_side_nav_list_template, l_pp.default_side_nav_list_template);
  cmp('default_nav_bar_list_template', l_ut.default_nav_bar_list_template, l_pp.default_nav_bar_list_template);
  dbms_output.put_line(case when l_diff = 0
    then 'Master, Dateipfad und Standard-Templates wie im Universal Theme.'
    else l_diff || ' Abweichung(en) zum Universal Theme (siehe oben).' end);
exception
  when no_data_found then
    dbms_output.put_line('(kein Theme 42 in der App – Abgleich entfällt)');
end;
/
declare
  l_current varchar2(3);
  l_ref     number;
begin
  select is_current, reference_id into l_current, l_ref
    from apex_application_themes
   where application_id = wwv_flow_application_install.get_application_id and theme_number = 145;
  if l_current = 'Yes' then
    dbms_output.put_line('Kracherl ist das aktuelle Theme der App – Änderungen sind sofort sichtbar.');
  else
    dbms_output.put_line('Nächste Schritte (nur im App Builder möglich, Anleitung: docs/THEME-VARIANTE.md):');
    if l_ref is not null then
      dbms_output.put_line('  1. App exportieren (Backup) – der Rückweg zum Universal Theme geht nur über dieses Backup.');
      dbms_output.put_line('  2. Shared Components > Themes > Kracherl > Theme Subscription > Unsubscribe');
      dbms_output.put_line('  3. Shared Components > Themes > Switch Theme: Universal Theme (42) -> Kracherl (145)');
    else
      dbms_output.put_line('  Shared Components > Themes > Switch Theme: Universal Theme (42) -> Kracherl (145)');
      dbms_output.put_line('  (Theme 145 ist bereits entkoppelt; der Rückweg geht nur über ein Backup von vor dem Unsubscribe.)');
    end if;
    dbms_output.put_line('Achtung (APEX 26.1): Switch Theme setzt Column Span und Start New Column aller Regionen und Items zurück.');
  end if;
end;
/
